    expect(screen.getByRole('button', {name: /正在检查/})).toBeDisabled();
    expect(screen.getByText('正在重新检查 B站登录…')).toBeVisible();
    expect(screen.getByRole('button', {name: '开始调查'})).toBeDisabled();
